// Tab.tsx
import React, { useState } from "react";
import "./Tabs.scss";
import { MpaIcon } from "../icon/MpaIcon";
import { SvgMpaIcon } from "../../assets/icons";
import { NumberBadge } from "../numberBadge";
import { useWindowSize } from "../../hooks";

export interface TabItem {
  label: string;
  badgeCount?: string;
  content: React.ReactNode;
  leadingIcon?: keyof typeof SvgMpaIcon | any;
  trailingIcon?: keyof typeof SvgMpaIcon | any;
  disabled?: boolean;
}

export interface TabsProps {

  /**
   * Unique identifier for the tabs component
   */
  id: string;
  /**
   * Tabs Data
  */
  tabs: TabItem[];

  /**
   * Set the default index of tab.
  */
  defaultIndex?: number;

  /**
   * action of tab change
   */
  onTabChange?: (index: number, label: string) => void;

  /**
   * Determines the colour of the tab: primary, secondary, tertiary.
  */
  colour?: "primary" | "secondary" | "tertiary";

  /**
   * Determine Show / Off the icon
  */
  showIcon?: boolean;
  /**
   * Determine color of the badge 
  */
  badgeColor?: "primary" | "secondary" | "tertiary" | "success" | "warning" | "error" | "surface" | "primary-soft" | "secondary-soft" | "tertiary-soft" | "success-soft" | "warning-soft" | "error-soft" | "surface-soft";
  /**
   * Determine Show / Off of the badge 
  */
  showBadge?: boolean;

  /**
   * Determine Show / Off of the divider 
  */
  showDivider?: boolean;

}

export const Tabs: React.FC<TabsProps> = ({
  id,
  tabs,
  defaultIndex = 0,
  colour = "primary",
  showIcon = true,
  showBadge = true,
  showDivider = true,
  badgeColor = "primary",
  onTabChange

}) => {
  const [activeIndex, setActiveIndex] = useState(defaultIndex);
  const { isMobile } = useWindowSize();
  const [isOpen, setIsOpen] = useState(false);

  const toggleDropdown = () => {
    setIsOpen(prev => !prev);
  }

  const handleTabClick = (index: number) => {
    if (!tabs[index].disabled) {
      setActiveIndex(index);
      onTabChange?.(index, tabs[index].label);
      setIsOpen(false);
    }
  };

  const tabClassName = `mpa-tab`;
  return (isMobile
    ? <div className={`${tabClassName}-mobile`}>
      <div className="tab-dropdown" onClick={() => toggleDropdown()}>
        <span className="selected-tab">{tabs[activeIndex].label}</span>
        <MpaIcon iconName={!isOpen ? "ChevronDown" : "ChevronUp"} />
      </div>
      {isOpen && (
        <div className="tab-dropdown-list">
          {tabs.map((tab, index) => (
            <div
              id={id}
              key={index}
              className={`tab-dropdown-option ${index === activeIndex ? "selected-tab" : ""}`}
              onClick={() => handleTabClick(index)}
            >
              {tab.label}
            </div>
          ))}
        </div>)
      }
      <div className="tab-content">
        {tabs[activeIndex]?.content}
      </div>
    </div>
    : <div className={`${tabClassName}`}>
      <div className="tab-header scroll-container">
        {tabs.map((tab, index) => (
          <div
            id={id}
            key={index}
            className={`tab-button ${colour} ${showDivider ? "showDivider" : ""} ${index === activeIndex ? "active" : ""} ${tab.disabled ? "disabled" : ""
              }`}
            onClick={() => handleTabClick(index)}
          >
            {tab.leadingIcon && showIcon && (
              <span>
                {typeof tab.leadingIcon === "string" && tab.leadingIcon in SvgMpaIcon ? (
                  <MpaIcon iconName={tab.leadingIcon} />
                ) : (
                  tab.leadingIcon
                )}
              </span>
            )}
            <span>{tab.label}</span>
            {showBadge && (
              <span>
                <NumberBadge id="badgeId" type="counter" label={tab.badgeCount} colour={badgeColor} />
              </span>
            )}
          </div>
        ))}
      </div>
      <div className="tab-content">
        {tabs[activeIndex]?.content}
      </div>
    </div>
  );
};

export default Tabs;
